CREATE TABLE IF NOT EXISTS word_labels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), label TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS oaf_samples (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), label_id UUID NOT NULL REFERENCES word_labels(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), feature_version VARCHAR(32) NOT NULL, feature_path TEXT NOT NULL, frame_count INTEGER NOT NULL, feature_count INTEGER NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), notes TEXT);
CREATE TABLE IF NOT EXISTS oaf_training_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), feature_version VARCHAR(32) NOT NULL, sample_count INTEGER NOT NULL, parameters JSONB NOT NULL, metrics JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS oaf_models (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), training_run_id UUID NOT NULL REFERENCES oaf_training_runs(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), model_path TEXT NOT NULL, weights JSONB NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS oaf_recognition_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), model_id UUID REFERENCES oaf_models(id), predicted_label TEXT, confidence REAL, feature_path TEXT, reviewed_label TEXT);
